-- Logs module (app/(LogsModule)): email_log (one row per sending attempt) and
-- staff_log (one row per staff action).
--
-- Prerequisites, the same as the repository baseline (compose.yml runs
-- PostgreSQL 18):
--   * PostgreSQL 18 or later: the shared ID default is the built-in uuidv7().
--   * The pg_trgm extension, already installed by 0004 for the user list; the
--     statement below is a no-op then. It needs a role that may create
--     extensions when it is missing; the migration fails loudly otherwise.
--
-- Generated by drizzle-kit from src/lib/db/schema/logs.ts, then extended by
-- hand with the extension statement above the tables and the triggers at the
-- end. drizzle-kit knows neither; preserve them when regenerating.
-- email_log references only itself (the retry chain, ON DELETE RESTRICT).
-- staff_log references the acting user (ON DELETE RESTRICT) and points at its
-- resource by type and ID without a foreign key. Index creation is
-- transactional, which is fine for these new, empty tables.
CREATE EXTENSION IF NOT EXISTS pg_trgm;
--> statement-breakpoint
CREATE TABLE "email_log" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"record_key" varchar(200) NOT NULL,
	"input_digest" char(64) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"started_at" timestamp with time zone NOT NULL,
	"completed_at" timestamp with time zone,
	"recipient_email" varchar(254) NOT NULL,
	"recipient_user_id" varchar(128),
	"recipient_label" varchar(200),
	"subject" varchar(500) NOT NULL,
	"content_text" text NOT NULL,
	"status" varchar(16) DEFAULT 'sending' NOT NULL,
	"provider" varchar(64),
	"provider_message_id" varchar(200),
	"error_code" varchar(100),
	"error_message" text,
	"stack_trace" text,
	"original_log_id" uuid,
	"previous_attempt_id" uuid,
	"attempt_number" integer NOT NULL,
	"requester_kind" varchar(16) NOT NULL,
	"requester_id" varchar(128),
	"requester_label" varchar(200) NOT NULL,
	"request_id" varchar(128) NOT NULL,
	"redaction_version" smallint DEFAULT 1 NOT NULL,
	"completion_digest" char(64),
	"search_text" text NOT NULL,
	CONSTRAINT "email_log_record_key_key" UNIQUE("record_key"),
	CONSTRAINT "email_log_status_check" CHECK ("email_log"."status" IN ('sending', 'accepted', 'failed', 'unknown')),
	CONSTRAINT "email_log_requester_check" CHECK (("email_log"."requester_kind" = 'user' AND "email_log"."requester_id" IS NOT NULL AND "email_log"."requester_id" <> '')
        OR ("email_log"."requester_kind" = 'anonymous' AND "email_log"."requester_id" IS NULL AND "email_log"."requester_label" = 'Anonymous')),
	CONSTRAINT "email_log_chain_check" CHECK (("email_log"."original_log_id" IS NULL AND "email_log"."previous_attempt_id" IS NULL AND "email_log"."attempt_number" = 1)
        OR ("email_log"."original_log_id" IS NOT NULL AND "email_log"."previous_attempt_id" IS NOT NULL
          AND "email_log"."original_log_id" <> "email_log"."id" AND "email_log"."previous_attempt_id" <> "email_log"."id"
          AND "email_log"."attempt_number" > 1)),
	CONSTRAINT "email_log_completion_check" CHECK (("email_log"."status" = 'sending' AND "email_log"."completed_at" IS NULL AND "email_log"."completion_digest" IS NULL)
        OR ("email_log"."status" <> 'sending' AND "email_log"."completed_at" IS NOT NULL
          AND "email_log"."completed_at" >= "email_log"."started_at" AND "email_log"."completion_digest" IS NOT NULL)),
	CONSTRAINT "email_log_recipient_email_check" CHECK ("email_log"."recipient_email" <> '' AND "email_log"."recipient_email" = lower("email_log"."recipient_email")),
	CONSTRAINT "email_log_text_check" CHECK ("email_log"."record_key" <> '' AND "email_log"."requester_label" <> '' AND "email_log"."request_id" <> ''
        AND "email_log"."subject" <> '' AND "email_log"."content_text" <> ''
        AND octet_length("email_log"."content_text") <= 131072
        AND ("email_log"."error_message" IS NULL OR char_length("email_log"."error_message") <= 4000)
        AND ("email_log"."stack_trace" IS NULL OR octet_length("email_log"."stack_trace") <= 32768)),
	CONSTRAINT "email_log_digest_check" CHECK ("email_log"."input_digest" ~ '^[0-9a-f]{64}$'
        AND ("email_log"."completion_digest" IS NULL OR "email_log"."completion_digest" ~ '^[0-9a-f]{64}$')),
	CONSTRAINT "email_log_redaction_version_check" CHECK ("email_log"."redaction_version" >= 1)
);
--> statement-breakpoint
CREATE TABLE "staff_log" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"actor_id" text NOT NULL,
	"action" varchar(150) NOT NULL,
	"resource_type" varchar(64) NOT NULL,
	"resource_id" varchar(128) NOT NULL,
	"message" jsonb NOT NULL,
	"message_text" text NOT NULL,
	CONSTRAINT "staff_log_action_check" CHECK ("staff_log"."action" ~ '^[a-z][a-z0-9_.-]{0,149}$'),
	CONSTRAINT "staff_log_resource_check" CHECK ("staff_log"."resource_type" <> '' AND "staff_log"."resource_id" <> ''),
	CONSTRAINT "staff_log_message_check" CHECK (jsonb_typeof("staff_log"."message") = 'array' AND jsonb_array_length("staff_log"."message") >= 1
        AND "staff_log"."message_text" <> '')
);
