-- An email attempt's initiation snapshot never changes after insertion; only
-- the status/observation columns written by completeEmailLog may. Status moves
-- sending -> accepted | failed | unknown, and unknown -> accepted | failed
-- once; accepted and failed are final.
CREATE FUNCTION "email_log_guard_update"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (NEW."id", NEW."record_key", NEW."input_digest", NEW."created_at", NEW."started_at",
      NEW."recipient_email", NEW."recipient_user_id", NEW."recipient_label", NEW."subject",
      NEW."content_text", NEW."provider", NEW."original_log_id", NEW."previous_attempt_id",
      NEW."attempt_number", NEW."requester_kind", NEW."requester_id", NEW."requester_label",
      NEW."request_id", NEW."redaction_version", NEW."search_text")
     IS DISTINCT FROM
     (OLD."id", OLD."record_key", OLD."input_digest", OLD."created_at", OLD."started_at",
      OLD."recipient_email", OLD."recipient_user_id", OLD."recipient_label", OLD."subject",
      OLD."content_text", OLD."provider", OLD."original_log_id", OLD."previous_attempt_id",
      OLD."attempt_number", OLD."requester_kind", OLD."requester_id", OLD."requester_label",
      OLD."request_id", OLD."redaction_version", OLD."search_text") THEN
    RAISE EXCEPTION 'email_log initiation columns are immutable'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NOT ((OLD."status" = 'sending' AND NEW."status" IN ('accepted', 'failed', 'unknown'))
       OR (OLD."status" = 'unknown' AND NEW."status" IN ('accepted', 'failed'))) THEN
    RAISE EXCEPTION 'email_log status % cannot change to %', OLD."status", NEW."status"
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER "email_log_guard_update" BEFORE UPDATE ON "email_log"
  FOR EACH ROW EXECUTE FUNCTION "email_log_guard_update"();
--> statement-breakpoint
-- The staff log is append-only: an entry is never edited or removed.
CREATE FUNCTION "staff_log_forbid_change"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'staff_log is append-only'
    USING ERRCODE = 'integrity_constraint_violation';
END;
$$;
--> statement-breakpoint
CREATE TRIGGER "staff_log_forbid_change" BEFORE UPDATE OR DELETE ON "staff_log"
  FOR EACH ROW EXECUTE FUNCTION "staff_log_forbid_change"();
